import{_ as t,o as a,c as o,a0 as r}from"./chunks/framework.Bmhw_dvp.js";const p=JSON.parse('{"title":"Orchestrator State Machine Verification","description":"Require robust completion verification for asynchronous Cloud Functions in the Firebase Orchestrator state machine to prevent pipeline race conditions.","frontmatter":{"isInternal":true,"type":"Architecture Decision Record","title":"Orchestrator State Machine Verification","description":"Require robust completion verification for asynchronous Cloud Functions in the Firebase Orchestrator state machine to prevent pipeline race conditions.","tags":["orchestrator","firebase","state-machine","automation","functions"]},"headers":[],"relativePath":"adr/2026-07-15-orchestrator-state-machine-verification.md","filePath":"adr/2026-07-15-orchestrator-state-machine-verification.md"}'),i={name:"adr/2026-07-15-orchestrator-state-machine-verification.md"};function n(s,e,c,l,u,d){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="orchestrator-state-machine-verification" tabindex="-1">Orchestrator State Machine Verification <a class="header-anchor" href="#orchestrator-state-machine-verification" aria-label="Permalink to &quot;Orchestrator State Machine Verification&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Our automation pipeline uses a central <code>orchestrator</code> Cloud Function that reacts to <code>workflowState</code> changes and executes pipeline steps (<code>executeStep</code> in <code>orchestrator.ts</code>).</p><h2 id="problem" tabindex="-1">Problem <a class="header-anchor" href="#problem" aria-label="Permalink to &quot;Problem&quot;">​</a></h2><p>A critical race condition occurred when the orchestrator executed <code>step_visuals</code>. The <code>executeStep</code> function called <code>runVisualizer</code>, awaited it, and immediately marked <code>step_visuals</code> as <code>&quot;complete&quot;</code> when <code>runVisualizer</code> returned. However, <code>runVisualizer</code> was silently catching internal image generation errors and returning <code>{success: true}</code> regardless of whether the visual assets were actually generated. This resulted in the state machine prematurely advancing to <code>step_video</code>, producing videos with missing image assets.</p><h2 id="solution" tabindex="-1">Solution <a class="header-anchor" href="#solution" aria-label="Permalink to &quot;Solution&quot;">​</a></h2><p>When a state machine orchestrator triggers background functions or long-running tasks:</p><ol><li><strong>Explicit Verification Gate:</strong> The task runner (e.g., <code>runVisualizer</code>) MUST explicitly verify that all requested outputs (e.g., all scenes have an <code>imageUrl</code>) exist and are valid before returning a success signal to the orchestrator.</li><li><strong>Fail Fast on Partial Errors:</strong> If any sub-task (like a single scene&#39;s generation) fails, the runner must accumulate these errors and THROW an explicit error before resolving.</li><li><strong>Automatic Retries:</strong> The runner should be configured to attempt processing on any inputs in an <code>&quot;error&quot;</code> state (not just <code>&quot;pending&quot;</code>), allowing users to click a &quot;Retry&quot; button on the UI to safely resume the orchestrator pipeline without getting permanently stuck on failed subsets.</li></ol><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Do NOT assume that awaiting an async function guarantees the output data was completely generated if that function suppresses errors. Always explicitly assert the final state of the data before advancing the workflow state.</p></div>',9)])])}const m=t(i,[["render",n]]);export{p as __pageData,m as default};
